"""HIP shared-memory lookup with tables generated by the original Triton math."""
import ctypes

_library = None


def library():
    global _library
    if _library is None:
        from .hip_libraries import ensure_library

        _library = ctypes.CDLL(
            str(ensure_library("torch_gate_shared.hip", "libtorch_gate_shared"))
        )
        fn = _library.openpi_torch_gate
        fn.argtypes = [ctypes.c_int] * 3 + [ctypes.c_void_p] * 7 + [ctypes.c_uint32]
        fn.restype = ctypes.c_int
    return _library.openpi_torch_gate


def call(kind, args, table, stream, config, n=507510784):
    if kind == "forward":
        x, up, out = args[:3]
        grad = None
        other = None
    else:
        up, grad, x, other = args[:4]
        out = up
    pointers = [
        t.data_ptr() if t is not None else None
        for t in [x, up, grad, table, out, other]
    ]
    error = library()(
        int(kind == "backward"), config["pairs"], config["grid"], stream, *pointers, n
    )
    if error:
        raise RuntimeError("shared gate HIP launch error " + str(error))
